programs.solution:
#include <iostream>
#include <iomanip>
using namespace std;
int main() {
    int n, count = 0, sum = 0;
    cin >> n;
    while (n != 0) {
        sum += n;
        count++;
        cin >> n;
    }
    if (count == 0) {
        cout << "No data" << endl;
    } else {
        cout << "Count: " << count << endl;
        cout << "Sum: " << sum << endl;
        cout << fixed << setprecision(2) << "Average: " << static_cast<double>(sum) / count << endl;
    }
    return 0;
}

#include <iostream>
using namespace std;
int main() {
    int size;
    cout << "Size (1-9):" << endl;
    cin >> size;
    while (size < 1 || size > 9) {
        cout << "Size (1-9):" << endl;
        cin >> size;
    }
    for (int r = 1; r <= size; r++) {
        for (int c = 1; c <= size; c++) {
            if (c > 1) cout << " ";
            cout << r * c;
        }
        cout << endl;
    }
    return 0;
}

