int main() {
    int n, steps = 0;
    cin >> n;
    cout << n;
    while (n != 1) {
        if (n % 2 == 0)
            n /= 2;
        else
            n = 3 * n + 1;
        steps++;
        cout << " " << n;
    }
    cout << endl << "Steps: " << steps << endl;
    return 0;
}

#include <iostream>
using namespace std;
int main() {
    int count = 0, sum = 0, largest = 0;
    for (int i = 0; i < 10; i++) {
        int v;
        cin >> v;
        if (v < 0)
            continue;
        if (v == 0)
            break;
        count++;
        sum += v;
        if (v > largest)
            largest = v;
    }
    cout << "Count: " << count << endl;
    cout << "Sum: " << sum << endl;
    cout << "Largest: " << largest << endl;
    return 0;
}
